#!/bin/bash
set -e
cd ~/localloop

echo "🌿 Local Loop — deploying new pages..."

# ── Check / install @supabase/supabase-js ──────────────────────────
if ! node -e "require('@supabase/supabase-js')" 2>/dev/null; then
  echo "📦 Installing @supabase/supabase-js..."
  npm install @supabase/supabase-js
else
  echo "✓ @supabase/supabase-js already installed"
fi

# ── Helper: decode base64 cross-platform ──────────────────────────
decode_b64() {
  if base64 --version 2>&1 | grep -q GNU; then
    echo "$1" | base64 --decode
  else
    echo "$1" | base64 -d
  fi
}


# ── 1. lib/supabase.ts ───────────────────────────────────────────
echo "📝 Writing lib/supabase.ts..."
mkdir -p lib
decode_b64 "" > lib/supabase.ts
git add lib/supabase.ts
git commit -m "Add shared Supabase client utility"
git push
echo "✓ lib/supabase.ts committed"

# ── 2. app/auth/signup/page.tsx ──────────────────────────────────
echo "📝 Writing signup page..."
mkdir -p app/auth/signup
decode_b64 "" > app/auth/signup/page.tsx
git add app/auth/signup/page.tsx
git commit -m "Add signup page with neighborhood, cross street, zip, verification photo"
git push
echo "✓ signup/page.tsx committed"

# ── 3. app/auth/login/page.tsx ───────────────────────────────────
echo "📝 Writing login page..."
mkdir -p app/auth/login
decode_b64 "" > app/auth/login/page.tsx
git add app/auth/login/page.tsx
git commit -m "Add login page"
git push
echo "✓ login/page.tsx committed"

# ── 4. app/listings/new/page.tsx ─────────────────────────────────
echo "📝 Writing new listing page..."
mkdir -p app/listings/new
decode_b64 "" > app/listings/new/page.tsx
git add app/listings/new/page.tsx
git commit -m "Add create listing page with up to 5 photo uploads"
git push
echo "✓ listings/new/page.tsx committed"

# ── 5. app/admin/page.tsx ────────────────────────────────────────
echo "📝 Writing admin dashboard..."
mkdir -p app/admin
decode_b64 "" > app/admin/page.tsx
git add app/admin/page.tsx
git commit -m "Add admin dashboard to approve/reject new users"
git push
echo "✓ admin/page.tsx committed"

echo ""
echo "🎉 All done! 5 files committed and pushed to GitHub."
echo "   Vercel will auto-deploy in ~60 seconds."
